def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--reference', required=True, type=Path)
    parser.add_argument('--output', type=Path, default=Path('docs/concat-effects-catalog.json'))
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    result = inventory(args.reference)
    encoded = json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False) + '\n'
    if args.check:
        if not args.output.exists() or args.output.read_text() != encoded:
            raise SystemExit('Concat effects catalog is stale')
    else:
        args.output.write_text(encoded)
    print(f'{len(result["packages"])} packages, {sum(len(p["parameters"]) for p in result["packages"])} parameter declarations; inventory only')


if __name__ == '__main__':
    main()
